   --color-bg: #f6f7fb;
   --color-surface: #ffffff;
   --color-text: #172033;
   --color-muted-text: #4f5f7a;
   --color-link: #2357d6;
   --color-border: #9aa7bd;
   --color-border-strong: #53627c;
   --color-focus: #8b3dff;
   --color-danger: #b42318;
   --color-success: #0f766e;
   --color-button-bg: #19376d;
   --color-button-hover: #102a55;
   --shadow-card: 0 24px 60px #d3d9e8;
 }

 * {
   box-sizing: border-box;
 }

 html {
   font-family:
     Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
     sans-serif;
   line-height: 1.5;
 }

 body {
   min-width: 320px;
   min-height: 100vh;
   margin: 0;
   color: var(--color-text);
   background:
     radial-gradient(circle at top left, #e7edff 0, transparent 34rem),
     linear-gradient(135deg, var(--color-bg), #eef2f7);
 }

 a {
   color: var(--color-link);
 }

 .skip-link {
   position: absolute;
   top: 1rem;
   left: 1rem;
   z-index: 1;
   padding: 0.6rem 0.85rem;
   border-radius: 999px;
   color: var(--color-surface);
   background: var(--color-button-bg);
   transform: translateY(-140%);
   transition: transform 160ms ease;
 }

 .skip-link:focus {
   transform: translateY(0);
 }

 .page-shell {
   display: grid;
   min-height: 100vh;
   padding: clamp(1rem, 4vw, 3rem);
   place-items: center;
 }

 .card {
   width: min(100%, 32rem);
   padding: clamp(1.5rem, 5vw, 3rem);
   border: 1px solid #d9e0ec;
   border-radius: 1.5rem;
   background: var(--color-surface);
   box-shadow: var(--shadow-card);
 }

 .eyebrow {
   margin: 0 0 0.65rem;
   color: var(--color-link);
   font-size: 0.78rem;
   font-weight: 800;
   letter-spacing: 0.08em;
   text-transform: uppercase;
 }

 h1 {
   margin: 0;
   font-size: clamp(2rem, 8vw, 3.25rem);
   line-height: 1.05;
   letter-spacing: -0.05em;
 }

 .intro {
   margin: 1rem 0 1.75rem;
   color: var(--color-muted-text);
   font-size: 1.05rem;
 }

 .required-note,
 .helper-text,
 .error-text,
 .status {
   margin: 0;
   font-size: 0.95rem;
 }

 .required-note {
   margin-bottom: 1rem;
   color: var(--color-muted-text);
 }

 .form-field {
   padding: 1rem;
   border: 1px solid var(--color-border);
   border-radius: 1rem;
   background: #fbfcff;
 }

 .checkbox-row {
   display: flex;
   align-items: flex-start;
   gap: 0.75rem;
 }

 input[type="checkbox"] {
   flex: 0 0 auto;
   width: 1.25rem;
   height: 1.25rem;
   margin: 0.15rem 0 0;
   accent-color: var(--color-button-bg);
 }

 label {
   color: var(--color-text);
   font-weight: 700;
 }

 .helper-text {
   margin-top: 0.45rem;
   padding-left: 2rem;
   color: var(--color-muted-text);
 }

 .error-text {
   margin-top: 0.55rem;
   padding-left: 2rem;
   color: var(--color-danger);
   font-weight: 700;
 }

 .form-field:has(input[aria-invalid="true"]) {
   border-color: var(--color-danger);
   background: #fffafa;
 }

 .button {
   width: 100%;
   min-height: 3rem;
   margin-top: 1.25rem;
   border: 0;
   border-radius: 999px;
   color: var(--color-surface);
   background: var(--color-button-bg);
   font: inherit;
   font-weight: 800;
   cursor: pointer;
 }

 .button:hover {
   background: var(--color-button-hover);
 }

 .status {
   min-height: 1.5rem;
   margin-top: 1rem;
   color: var(--color-success);
   font-weight: 700;
 }

 :focus-visible {
   outline: 3px solid transparent;
   box-shadow: 0 0 0 4px var(--color-focus);
 }

 @media (prefers-reduced-motion: reduce) {
   *,
   *::before,
   *::after {
     scroll-behavior: auto !important;
     transition-duration: 0.01ms !important;
   }
 }

 @media (forced-colors: active) {
   .card,
   .form-field,
   .button {
     border: 1px solid ButtonBorder;
   }

   .button,
   .skip-link {
     color: ButtonText;
     background: ButtonFace;
   }
 }

')

