         cursor: pointer;
       }

       .button:hover {
         background: var(--color-button-hover);
       }

       .status {
         min-height: 1.5rem;
         margin-top: 1rem;
         color: var(--color-success);
         font-weight: 700;
       }

       :focus-visible {
         outline: 3px solid transparent;
         box-shadow: 0 0 0 4px var(--color-focus);
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
         }
       }

       @media (forced-colors: active) {
         .card,
         .form-field,
         .button {
           border: 1px solid ButtonBorder;
         }

         .button,
         .skip-link {
           color: ButtonText;
           background: ButtonFace;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>

     <main id="main" class="page-shell">
       <section class="card" aria-labelledby="form-title">
         <p class="eyebrow">Account access</p>
         <h1 id="form-title">Review and continue</h1>
         <p class="intro">Confirm your consent before moving on to the product experience.</p>

         <form id="consent-form" novalidate>
           <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

           <div class="form-field">
             <div class="checkbox-row">
               <input
                 id="terms-consent"
                 name="termsConsent"
                 type="checkbox"
                 required
                 aria-describedby="terms-help"
               >
               <label for="terms-consent">
                 I agree to the terms of use <span aria-hidden="true">*</span>
               </label>
             </div>
             <p id="terms-help" class="helper-text">Required to create and manage your account.</p>
             <p id="terms-error" class="error-text" hidden>Error: Agree to the terms of use to continue.</p>
           </div>

           <button class="button" type="submit">Continue</button>
           <p id="form-status" class="status" role="status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#consent-form");
       const consent = document.querySelector("#terms-consent");
       const error = document.querySelector("#terms-error");
       const status = document.querySelector("#form-status");

       function showConsentError() {
         consent.setAttribute("aria-invalid", "true");
         consent.setAttribute("aria-describedby", "terms-help terms-error");
         error.hidden = false;
       }

       function clearConsentError() {
         consent.removeAttribute("aria-invalid");
         consent.setAttribute("aria-describedby", "terms-help");
         error.hidden = true;
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         if (!consent.checked) {
           showConsentError();
           consent.focus();
           return;
         }

         clearConsentError();
         status.textContent = "Ready to continue. Your consent has been recorded.";
       });

       consent.addEventListener("change", () => {
         if (consent.checked) {
           clearConsentError();
         }
       });
     </script>
   </body>
 </html>

')
